head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt50103";
scwin.progressScreen = null;
scwin.obj = undefined;
scwin.frameId = undefined;
scwin.frame = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

scwin.form_editForm = { action: "", method: 'post', target: '' };

try { scwin.obj =opener.Potential.Provider; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50103' }); }

try { scwin.frameId =scwin.obj.ActiveFrame.FrameID; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50103' }); }

try { scwin.frame =scwin.obj.Provider(scwin.frameId).ActiveFrame; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50103' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.progressScreen = $c.util.getComponent('progressScreen');
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50103.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_62_onclick
 * @description img_62 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_62_onclick = async function(e){
    try {
        await scwin.confirm()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50103.img_62_onclick' }); }
};

/**
 * @method
 * @name img_63_onclick
 * @description img_63 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_63_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50103.img_63_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Confirm
 * @description Confirm 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Confirm = async function () {
    const sbmOptions = {
        id: "tx_fn_Confirm",
        method: "post",
        action: "/filing/extractElement.do",
        ref: "dma_ConfirmReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name confirm
 * @description confirm 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.confirm = async function () {
    scwin.progressScreen.setStyle("display", "block");
    $c.util.getComponent('dma_ConfirmReq').set('method', "reExtractElement");
    scwin.form_editForm.action = "/filing/extractElement.do";
    await scwin.tx_fn_Confirm();
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};
